import pandas as pd
import ast
import math
from collections import defaultdict

def edit_distance(s1, s2):
    if len(s1) > len(s2):
        s1, s2 = s2, s1
    distances = range(len(s1) + 1)
    for index2, char2 in enumerate(s2):
        new_distances = [index2 + 1]
        for index1, char1 in enumerate(s1):
            if char1 == char2:
                new_distances.append(distances[index1])
            else:
                new_distances.append(1 + min((distances[index1], distances[index1+1], new_distances[-1])))
        distances = new_distances
    return distances[-1]

def get_billing_month(date_str):
    if '2025-03-04' <= date_str <= '2025-03-31': return 3
    if '2025-04-01' <= date_str <= '2025-05-05': return 4
    if '2025-05-06' <= date_str <= '2025-06-02': return 5
    if '2025-06-03' <= date_str <= '2025-06-30': return 6
    return None

def answer() -> dict:
    df_emp = pd.read_csv('/app/dataset/employees.csv')
    df_tasks = pd.read_csv('/app/dataset/tasks.csv')
    df_ts = pd.read_csv('/app/dataset/timesheet.csv')

    valid_pesel = set(df_emp['PESEL'].astype(str))
    emp_rates = dict(zip(df_emp['PESEL'].astype(str), df_emp['hourly_rate']))
    valid_tasks = set(df_tasks['task_id'].astype(str))
    task_pay = dict(zip(df_tasks['task_id'].astype(str), df_tasks['pay_per_completion']))

    salary_by_period = defaultdict(lambda: defaultdict(int))
    pesel_correction = {}

    for _, row in df_ts.iterrows():
        date_str = str(row['date'])
        try:
            pd.to_datetime(date_str, format='%Y-%m-%d')
        except:
            continue

        bm = get_billing_month(date_str)
        if bm is None:
            continue

        emp_id = str(row['employee_id'])
        if emp_id not in valid_pesel:
            if emp_id in pesel_correction:
                emp_id = pesel_correction[emp_id]
            else:
                dists = [(edit_distance(emp_id, e), e) for e in valid_pesel]
                dists.sort()
                if dists[0][0] <= 3 and (len(dists) == 1 or dists[1][0] > dists[0][0]):
                    pesel_correction[emp_id] = dists[0][1]
                    emp_id = dists[0][1]
                else:
                    continue

        t_str = row['performed_tasks']
        is_valid = True
        parsed_tasks = []
        if not pd.isna(t_str):
            t_str_fix = str(t_str)
            if not t_str_fix.startswith('['): t_str_fix = '[' + t_str_fix
            if not t_str_fix.endswith(']'): t_str_fix = t_str_fix + ']'
            try:
                tasks_list = [str(x) for x in ast.literal_eval(t_str_fix)]
                for t in tasks_list:
                    if t not in valid_tasks:
                        is_valid = False
                        break
                parsed_tasks = tasks_list
            except:
                is_valid = False

        if not is_valid:
            continue

        hours = int(row['hours_worked'])
        base = hours * emp_rates[emp_id]
        bonus = sum(task_pay[t] for t in parsed_tasks)

        salary_by_period[emp_id][bm] += (base + bonus)

    result = {}
    for pesel in valid_pesel:
        monthly_salaries = []
        for m in sorted([3, 4, 5, 6]):
            val = salary_by_period[pesel].get(m, 0)
            monthly_salaries.append(int(math.floor(val + 0.5)))
        result[pesel] = monthly_salaries

    return result

if __name__ == "__main__":
    res = answer()
    for k, v in list(res.items())[:5]:
        print(k, v)
